/// <summary>
/// Fill ReqPO Rum fields by exploding requirement for origin sales order
/// </summary>
public class AVARUMReqPoExplodeSales
{
    Counter cnt;

}

Method.Source:
 /// <summary>
 /// Fill Rum fields for on ReqPo
 /// Creates the upwards exlosure and searches for the initiator sales line
 /// </summary>
 /// <param name = "_reqPo">Planned order to fill</param>
 /// <param name = "_recIdPlanVersion">PlanVersion for which to run</param>
public void fillForTransid(ReqPO _reqPo, RecId _recIdPlanVersion)
 {
     //@analogous to AtlCommandReqExplode::executeAndGetRequirementTransactions
     ReqTrans        reqTransCaller = ReqTrans::findCommon(_recIdPlanVersion, _reqPo);
     ReqTransExplode reqTransExplode = ReqTransExplode::newReqTrans(reqTransCaller, ReqExplodeType::Up, false);

     reqTransExplode.run();

     ttsbegin;
     ReqPO       locReqPo;
     Map         map=Map::create(reqTransExplode.packMapReqTrans());
     MapIterator mi=new MapIterator(map);
     while (mi.more())
     {            
         ReqTrans locReqTrans=mi.value();
         if (locReqTrans.RefType==ReqRefType::Sales)
         {
             locReqPo=ReqPO::findRecId(_reqPo.RecId, true);
             locReqPo.AVARUMSalesId=locReqTrans.RefId;                
             SalesTable locSalesTable=SalesTable::find(locReqTrans.RefId);
             locReqPo.AVARUMCustAccount=locSalesTable.CustAccount;
             locReqPo.AVARUMDeliveryDate=(locSalesTable.ShippingDateConfirmed ? locSalesTable.ShippingDateConfirmed :
                 locSalesTable.ShippingDateRequested);
             locReqPo.update();
             cnt++;
             break;
         }

         mi.next();
     }
     ttscommit;        
 }

/// <summary>
/// Run fillup procedure for all ReqPo for given plan
/// </summary>
/// <param name = "_planId">Plan to run for</param>
public void runAll(ReqPlanId _planId)
{
    ReqPlanVersion planVersion = ReqPlan::findReqPlanId(_planId).findActiveVersion();
    ReqPO locReqPo;
    int tstart, tend;

    tstart=DateTimeUtil::getTimeNow(Timezone::GMTPLUS0100_AMSTERDAM_BERLIN_BERN_ROME);

    while select * from locReqPo
        where locReqPo.PlanVersion==planVersion.RecId
          && (locReqPo.RefType==ReqRefType::BOMPlannedOrder
            ||locReqPo.RefType==ReqRefType::PmfPlannedProdBatch)        
    {
        this.fillForTransid(locReqPo, planVersion.recid);

    }
    tend=DateTimeUtil::getTimeNow(Timezone::GMTPLUS0100_AMSTERDAM_BERLIN_BERN_ROME);
    new SysExceptionLog().writeEntry(Exception::info, strFmt("@AVARUM:AVARUMReqPoExplodeSalesMsg2", cnt, time2Str(tStart, -1, -1), time2Str(tEnd, -1, -1)), "@AVARUM:AVARUMReqPoExplodeSalesMsg1");
}

/// <summary>
/// Test code for dirct calling and execution for all ReqPos of current plan 
/// </summary>
/// <param name = "_args">Main args, can remain empty</param>
static public void main(Args _args)
{   
    new AVARUMReqPoExplodeSales().runAll(ReqParameters::find().CurrentReqPlanIdSchedDynamic);

}
